fun main() {
    val fullName = "Android Class"
    val username = "android_2025"
    val gender = "Male"
    val password = "android@1234"
    val confirmPassword = "android@1234"

    val fieldErrors = mutableMapOf<String, String>()

    when {
        fullName.isEmpty() -> fieldErrors["fullName"] = "Full name cannot be empty"
        username.isEmpty() -> fieldErrors["username"] = "Username cannot be empty"
        gender.isEmpty() -> fieldErrors["gender"] = "Gender cannot be empty"
        password.isEmpty() -> fieldErrors["password"] = "Password cannot be empty"
        confirmPassword.isEmpty() -> fieldErrors["confirmPassword"] = "Confirm password cannot be empty"
        password.length <= 6 -> fieldErrors["password"] = "Password should be more than 6 digits"
        password != confirmPassword -> fieldErrors["confirmPassword"] = "Password and confirm password should match"
        else -> {
            println("Signup Successful")
            println("Navigating to Dashboard")
            println("finish() called")
        }
    }

    if (fieldErrors.isNotEmpty()) {
        fieldErrors.forEach { (field, message) ->
            println("$field: $message")
        }
    }
}
